// Covariance: a producer of Dog can be consumed as a producer of Animal
IEnumerable<Dog> dogs = new List<Dog> { new() };
IEnumerable<Animal> animals = dogs;          // legal — out T
foreach (var a in animals) Console.WriteLine(a.Name);  // reading only — safe

Func<Animal> nextAnimal = () => new Dog();  // Func's TResult is covariant
Func<Dog> nextDog = nextAnimal;             // Func<Animal> IS-A Func<Dog>

// Contravariance: a consumer of Animal can be used as a consumer of Dog
Action<Animal> logAnimal = a => Console.WriteLine(a.Name);
Action<Dog> logDog = logAnimal;             // legal — in T
logDog(new Dog());                          // passing a Dog where Animal is handled — safe

IComparer<Animal> byName = Comparer<Animal>.Create((x, y) => string.Compare(x.Name, y.Name));
IComparer<Dog> dogByName = byName;          // a Dog sorter is just a special Animal sorter
List<Dog> sorted = dogs.OrderBy(d => d, dogByName).ToList();

// ❌ Invariance: List both produces AND consumes T, so no conversion
List<Dog> dogList = new();
// List<Animal> animalList = dogList;       // compile error — List<T> is invariant

// ❌ The array covariance trap (why generics are better)
Dog[] dogArray = { new Dog() };
Animal[] animalArray = dogArray;            // arrays are covariant — unchecked!
try { animalArray[0] = new Cat(); }         // runtime ArrayTypeMismatchException
catch (ArrayTypeMismatchException) { /* the hole generics closed */ }

